SELECT [tableName] COLLATE DATABASE_DEFAULT AS [tableName],[name] COLLATE DATABASE_DEFAULT AS [name],[type_desc] COLLATE DATABASE_DEFAULT AS [type_desc],[filter_definition] COLLATE DATABASE_DEFAULT AS [filter_definition],[columnName] COLLATE DATABASE_DEFAULT AS [columnName],[is_unique],[is_primary_key],[is_unique_constraint],[is_disabled],[is_descending_key],[is_included_column],[key_ordinal],[index_column_id] INTO #Expected_indexes FROM OPENJSON(@expected) WITH ([tableName] nvarchar(4000) '$.tableName',[name] nvarchar(4000) '$.name',[type_desc] nvarchar(4000) '$.type_desc',[filter_definition] nvarchar(4000) '$.filter_definition',[columnName] nvarchar(4000) '$.columnName',[is_unique] bit '$.is_unique',[is_primary_key] bit '$.is_primary_key',[is_unique_constraint] bit '$.is_unique_constraint',[is_disabled] bit '$.is_disabled',[is_descending_key] bit '$.is_descending_key',[is_included_column] bit '$.is_included_column',[key_ordinal] int '$.key_ordinal',[index_column_id] int '$.index_column_id');
SELECT [tableName] COLLATE DATABASE_DEFAULT AS [tableName],[name] COLLATE DATABASE_DEFAULT AS [name],[type_desc] COLLATE DATABASE_DEFAULT AS [type_desc],[filter_definition] COLLATE DATABASE_DEFAULT AS [filter_definition],[columnName] COLLATE DATABASE_DEFAULT AS [columnName],[is_unique],[is_primary_key],[is_unique_constraint],[is_disabled],[is_descending_key],[is_included_column],[key_ordinal],[index_column_id] INTO #Actual_indexes FROM (SELECT t.name tableName,i.name,i.type_desc,i.is_unique,i.is_primary_key,i.is_unique_constraint,i.is_disabled,i.filter_definition,i.fill_factor,i.is_padded,i.ignore_dup_key,i.allow_row_locks,i.allow_page_locks,c.name columnName,ic.key_ordinal,ic.is_descending_key,ic.is_included_column,ic.index_column_id FROM sys.tables t JOIN sys.indexes i ON i.object_id=t.object_id LEFT JOIN sys.index_columns ic ON ic.object_id=i.object_id AND ic.index_id=i.index_id LEFT JOIN sys.columns c ON c.object_id=ic.object_id AND c.column_id=ic.column_id WHERE i.index_id>0) actual;
IF EXISTS (SELECT * FROM #Expected_indexes EXCEPT SELECT * FROM #Actual_indexes) OR EXISTS (SELECT * FROM #Actual_indexes EXCEPT SELECT * FROM #Expected_indexes)
BEGIN
 SELECT 'Missing or changed' AS Difference,* FROM (SELECT * FROM #Expected_indexes EXCEPT SELECT * FROM #Actual_indexes) missing;
 SELECT 'Unexpected or changed' AS Difference,* FROM (SELECT * FROM #Actual_indexes EXCEPT SELECT * FROM #Expected_indexes) extra;
 THROW 51001, 'Verify indexes failed.', 1;
END;
DROP TABLE #Expected_indexes; DROP TABLE #Actual_indexes;
PRINT 'PASS indexes';
GO
